INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-serum-lumiere', 'serum-lumiere', 'Sérum Lumière', 'Skincare', 'Brightening face serum', 'A weightless botanical serum pressed from cold-extracted Nigerian baobab seed and vitamin-rich hibiscus calyx. It sinks in without residue to soften hyperpigmentation and leave melanin-rich skin with a calm, even radiance.', NULL, '["Cold-pressed northern Nigerian baobab seed oil","Kano hibiscus sabdariffa extract (natural alpha-hydroxy acids)","Niacinamide (5%) and licorice root filtrate","Fermented Bambara groundnut humectant complex"]'::jsonb, 'Press three to four drops into damp skin after cleansing, morning and evening. Follow with Huile Visage or Crème Velours to seal in moisture.', true, 1) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use;
