INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-creme-velours', 'creme-velours', 'Crème Velours', 'Skincare', 'Rich night cream (unrefined shea)', 'Whipped from unrefined northern Nigerian shea butter harvested in Kwara and Niger states, tempered with moringa lipid extract. It melts on contact to mend dry barriers overnight so skin wakes supple and rested.', NULL, '["Unrefined hand-kneaded northern Nigerian Vitellaria paradoxa (shea) butter","Cold-pressed Zaria moringa oleifera seed oil","Plant-derived ceramide NP and squalane","Distilled rosewater and chamomile flower infusion"]'::jsonb, 'Warm a pea-sized amount between your fingertips until translucent, then press gently over face, neck and décolletage as the final step of your evening ritual.', true, 2) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use;
