INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-huile-visage', 'huile-visage', 'Huile Visage', 'Skincare', 'Nourishing face oil (baobab, moringa)', 'An intimate blend of first-press Nigerian baobab and moringa oils that mirrors the skin’s natural sebum. It cushions melanin-rich skin against harmattan dryness and urban air while imparting a quiet, satin sheen.', NULL, '["Organic Nigerian Adansonia digitata (baobab) seed oil","Cold-pressed Moringa oleifera seed oil","Marula and prickly pear seed oil","Natural tocopherol (vitamin E) from sunflower seed"]'::jsonb, 'Massage two to three drops into freshly misted skin or blend a single drop into Crème Velours when the air feels dry.', true, 3) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use;
