INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-ambre-sacre', 'ambre-sacre', 'Ambre Sacré', 'Roll-ons', 'Attar roll-on, amber', 'Alcohol-free golden labdanum and roasted tonka macerated in fractionated moringa oil. Sized for a pocket or evening bag, it glides onto warm skin with a resinous, candlelit glow.', '{"top":"Bitter orange rind, Ceylon cinnamon bark, nutmeg flower","heart":"Andalusian cistus labdanum, golden myrrh tear, beeswax absolute","base":"Roasted tonka bean, Siam benzoin, warm sandalwood oil"}'::jsonb, NULL, 'Roll gently across the wrists, hollow of the throat or fingertips before pressing into the ends of the hair.', true, 8) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use;
