INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-rose-taifi', 'rose-taifi', 'Rose Taïfi', 'Roll-ons', 'Attar roll-on, rose', 'Bright mountain rose co-distilled with white sandalwood in the traditional deg-bhapka manner. Fresh, spiced and never powdery, it captures rose petals still cool with morning dew.', '{"top":"Crushed Taif rose petal, green stem sap, lemon verbena leaf","heart":"Damask rose absolute, clove bud, pomegranate rind","base":"Aged white sandalwood, soft musk, trace honeyed oud"}'::jsonb, NULL, 'Glide onto pulse points throughout the day, or layer beneath Oud Mubakhar to add a floral lift to pure agarwood.', true, 9) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use;
