INSERT INTO products (id, slug, name, category, type, description, notes, ingredients, how_to_use, is_published, sort_order) VALUES ('prod-huile-precieuse', 'huile-precieuse', 'Huile Précieuse', 'Oils', 'Dry body oil', 'Pressed from northern Nigerian shea olein, baobab and Desert Date (adua) oil, this fast-absorbing body oil leaves melanin-rich skin gleamed and supple without transferring onto clothes. Lightly scented with warm fig leaf and cedar.', '{"top":"Crushed green fig leaf, petitgrain bigarade","heart":"Warm shea blossom, toasted sesame seed, white cedar","base":"Vetiver root, creamy sandalwood, soft amber"}'::jsonb, '["Fractionated northern Nigerian Vitellaria paradoxa (shea) olein","Cold-pressed Adansonia digitata (baobab) and Balanites aegyptiaca (desert date) oils","Squalane and vitamin E","Botanical fig leaf and cedarwood essential oil blend"]'::jsonb, 'Smooth generously over damp skin immediately after stepping out of the shower, paying extra attention to shins, elbows and collarbones.', true, 11) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, notes = EXCLUDED.notes, ingredients = EXCLUDED.ingredients, how_to_use = EXCLUDED.how_to_use;
